            // Update full and empty based on current count
            full <= (count == 3'd4);
            empty <= (count == 3'd0);

            // Write operation
            if (wr_en && !full) begin
                mem[wp] <= din;
                wp <= wp + 2'd1;
                count <= count + 3'd1;
            end

            // Read operation
            if (rd_en && !empty) begin
                dout <= mem[rp];
                rp <= rp + 2'd1;
                count <= count - 3'd1;
            end
        end
    end

endmodule

module fifo4 (
    input clk,
    input reset,
    input wr_en,
    input rd_en,
    input [7:0] din,
    output reg [7:0] dout,
    output reg full,
    output reg empty,
    output reg [2:0] count
);

    reg [1:0] wp, rp;
    reg [7:0] mem [0:3];

    always @(posedge clk) begin
        if (reset) begin
            wp <= 2'd0;
            rp <= 2'd0;
            count <= 3'd0;
            full <= 1'b0;
            empty <= 1'b1;
            dout <= 8'd0;
        end else begin
            // Update full and empty based on current count
            full <= (count == 3'd4);
            empty <= (count == 3'd0);

            // Write operation
            if (wr_en && !full) begin
                mem[wp] <= din;
                wp <= wp + 2'd1;
                count <= count + 3'd1;
            end

            // Read operation
            if (rd_en && !empty) begin
                dout <= mem[rp];
                rp <= rp + 2'd1;
                count <= count - 3'd1;
            end
        end
    end

endmodule
